#!/usr/bin/env python3
"""Validate and unpack a Storyboard Anchor Studio project."""
from __future__ import annotations

import argparse
import base64
import json
import re
import sys
from pathlib import Path

META = {
    "character": ("GREEN", "CHARACTER ANCHOR"),
    "setting": ("BROWN", "SETTING / SCENE"),
    "artifact": ("RED", "WEAPON / ARTIFACT"),
}


def safe_name(value: str, fallback: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", value.strip()).strip("._")
    return cleaned[:80] or fallback


def decode_data_url(value: str, target: Path) -> None:
    match = re.fullmatch(r"data:([^;,]+)?(;base64)?,(.*)", value, re.DOTALL)
    if not match:
        raise ValueError("image is not an embedded data URL")
    payload = match.group(3)
    raw = base64.b64decode(payload, validate=True) if match.group(2) else payload.encode()
    target.write_bytes(raw)


def image_ext(value: str) -> str:
    mime = value[5:value.find(";")].lower() if value.startswith("data:") else ""
    return {"image/png": ".png", "image/webp": ".webp", "image/gif": ".gif"}.get(mime, ".jpg")


def reference_label(asset: dict, index: int) -> str:
    color, category = META[asset["type"]]
    sheet, item = index // 6 + 1, index % 6 + 1
    return f"{color} · SHEET {sheet:02d} · {category} {item:02d} · {asset['name'].upper()}"


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("project", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()

    try:
        data = json.loads(args.project.read_text(encoding="utf-8"))
    except Exception as exc:
        print(f"ERROR: cannot read project: {exc}", file=sys.stderr)
        return 2

    errors, warnings = [], []
    assets, shots = data.get("assets"), data.get("shots")
    if not isinstance(assets, list): errors.append("assets must be an array")
    if not isinstance(shots, list): errors.append("shots must be an array")
    if errors:
        print("ERROR: " + "; ".join(errors), file=sys.stderr)
        return 2

    ids, names = set(), set()
    for i, asset in enumerate(assets):
        if not isinstance(asset, dict): errors.append(f"asset {i + 1} is not an object"); continue
        for field in ("id", "type", "name", "image"):
            if not asset.get(field): errors.append(f"asset {i + 1} missing {field}")
        if asset.get("type") not in META: errors.append(f"asset {i + 1} has invalid type")
        if asset.get("id") in ids: errors.append(f"duplicate asset id {asset.get('id')}")
        ids.add(asset.get("id"))
        lowered = str(asset.get("name", "")).casefold()
        if lowered in names: warnings.append(f"duplicate asset name: {asset.get('name')}")
        names.add(lowered)

    for i, shot in enumerate(shots):
        if not isinstance(shot, dict): errors.append(f"shot {i + 1} is not an object"); continue
        for field in ("id", "name", "image", "refs"):
            if field not in shot: errors.append(f"shot {i + 1} missing {field}")
        if not isinstance(shot.get("refs", []), list): errors.append(f"shot {i + 1} refs must be an array")
        for ref in shot.get("refs", []):
            if ref not in ids: errors.append(f"shot {i + 1} references missing asset id {ref}")

    if errors:
        print("ERROR:\n- " + "\n- ".join(errors), file=sys.stderr)
        return 2

    out = args.output
    refs_dir, scenes_dir, prompts_dir = out / "references", out / "scenes", out / "prompts"
    for directory in (refs_dir, scenes_dir, prompts_dir): directory.mkdir(parents=True, exist_ok=True)

    by_id, manifest_assets = {}, []
    index_lines = []
    for i, asset in enumerate(assets):
        label = reference_label(asset, i)
        ext = image_ext(asset["image"])
        target = refs_dir / f"S{(i // 6 + 1):02d}_A{(i % 6 + 1):02d}_{safe_name(asset['name'], 'reference')}{ext}"
        try: decode_data_url(asset["image"], target)
        except Exception as exc: errors.append(f"cannot decode {label}: {exc}"); continue
        entry = {"id": asset["id"], "label": label, "type": asset["type"], "name": asset["name"], "notes": asset.get("notes", ""), "path": str(target.resolve())}
        by_id[asset["id"]] = entry
        manifest_assets.append(entry)
        index_lines.extend([label, f"File: {entry['path']}", f"Continuity: {entry['notes'] or 'Preserve uploaded anchor exactly.'}", ""])

    manifest_shots = []
    for i, shot in enumerate(shots):
        number = i + 1
        scene = scenes_dir / f"SHOT_{number:02d}_BLUEPRINT_{safe_name(shot['name'], 'scene')}{image_ext(shot['image'])}"
        try: decode_data_url(shot["image"], scene)
        except Exception as exc: errors.append(f"cannot decode shot {number}: {exc}"); continue
        selected = [by_id[r] for r in shot.get("refs", []) if r in by_id]
        prompt = (
            f"PROJECT / STORY: {data.get('projectName') or 'Untitled Storyboard'}\n"
            f"SEQUENCE: {data.get('sequenceName') or 'Unspecified sequence'}\n"
            f"SHOT {number:02d}: {shot['name']}\n"
            f"SCENE BLUEPRINT: {scene.resolve()}\n"
            f"DURATION: {shot.get('duration') or 'Not specified'}\n"
            f"CAMERA: {shot.get('camera') or 'Follow uploaded composition'}\n"
            f"ACTION / STAGING: {shot.get('instructions') or 'Read and preserve the entire scene composition.'}\n"
            f"DIALOGUE / AUDIO: {shot.get('dialogue') or 'Not specified'}\n\n"
            "SELECTED AUTHORITATIVE REFERENCES:\n" +
            ("\n".join(f"- {a['label']}\n  File: {a['path']}\n  Continuity: {a['notes'] or 'Preserve exactly.'}" for a in selected) or "- None selected") +
            "\n\nTASK: Analyze the complete scene blueprint in relation to every selected locked reference. Rebuild the entire scene as one clean cinematic 16:9 storyboard image. Preserve subject count, geography, positions, action, identity, wardrobe, proportions, settings, weapons, artifacts, and vehicles. Remove all numbers, labels, markers, selection indicators, and reference-card text from the finished image. Do not invent, embellish, duplicate, merge, or replace any character or object."
        )
        prompt_path = prompts_dir / f"SHOT_{number:02d}_MASTER_SPEC.txt"
        prompt_path.write_text(prompt, encoding="utf-8")
        manifest_shots.append({"number": number, "id": shot["id"], "name": shot["name"], "scene_path": str(scene.resolve()), "prompt_path": str(prompt_path.resolve()), "references": selected})

    if errors:
        print("ERROR:\n- " + "\n- ".join(errors), file=sys.stderr)
        return 2

    manifest = {"format": "Storyboard Arcade Package", "version": 1, "projectName": data.get("projectName", ""), "sequenceName": data.get("sequenceName", ""), "assets": manifest_assets, "shots": manifest_shots, "warnings": warnings}
    (out / "manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    (out / "reference-index.txt").write_text("\n".join(index_lines), encoding="utf-8")
    print(json.dumps({"status": "ready", "output": str(out.resolve()), "assets": len(manifest_assets), "shots": len(manifest_shots), "warnings": warnings}, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
